namespace sv_4f1484f67c544667b39d1004e516a207.Services;

public record Channel(int Id, string Name, string Description, int UnreadCount);
public record Message(int Id, int ChannelId, string Author, string Content, DateTime SentAt, int? ReplyToId, List<Reaction> Reactions);
public record Reaction(string Emoji, List<string> Users);
public record ThreadSummary(int RootMessageId, int ReplyCount, DateTime LastReplyAt);

public interface IChatService
{
    Task<List<Channel>> GetChannelsAsync();
    Task<List<Message>> GetMessagesAsync(int channelId, int skip, int take);
    Task<Message> SendMessageAsync(int channelId, string content, int? replyToId);
    Task<List<Message>> GetThreadAsync(int rootMessageId);
    Task AddReactionAsync(int messageId, string emoji);
    Task MarkChannelReadAsync(int channelId);
}

namespace sv_4f1484f67c544667b39d1004e516a207.Services;

public class MockChatService : IChatService
{
    private readonly List<Channel> _channels;
    private readonly List<Message> _messages;
    private int _nextMessageId;

    public MockChatService()
    {
        _channels = new List<Channel>
        {
            new(1, "general", "General discussion and announcements", 3),
            new(2, "engineering", "Engineering team discussions", 0),
            new(3, "design", "Design reviews and feedback", 1),
            new(4, "random", "Off-topic conversations", 5),
            new(5, "deployments", "Deployment notifications and status", 0),
        };

        var now = DateTime.UtcNow;
        _messages = new List<Message>
        {
            new(1, 1, "Alice", "Hey team! Welcome to the new chat platform. 🎉", now.AddHours(-5), null, new List<Reaction>
            {
                new("👍", new List<string> { "Bob", "Carol", "Dave" }),
                new("🎉", new List<string> { "Eve", "Frank" }),
            }),
            new(2, 1, "Bob", "Looks great! Love the new design.", now.AddHours(-4.5), null, new List<Reaction>
            {
                new("❤️", new List<string> { "Alice" }),
            }),
            new(3, 1, "Carol", "Quick question — are we migrating the old messages?", now.AddHours(-4), null, new List<Reaction>()),
            new(4, 1, "Alice", "Yes, we plan to migrate everything by end of week.", now.AddHours(-3.8), 3, new List<Reaction>
            {
                new("👍", new List<string> { "Carol" }),
            }),
            new(5, 1, "Dave", "Can we get dark mode?", now.AddHours(-3), null, new List<Reaction>
            {
                new("😂", new List<string> { "Bob", "Eve" }),
                new("👀", new List<string> { "Frank" }),
            }),
            new(6, 1, "Eve", "Already on the roadmap!", now.AddHours(-2.5), 5, new List<Reaction>()),
            new(7, 1, "Frank", "I'm working on the notification system. Should be ready tomorrow.", now.AddMinutes(-45), null, new List<Reaction>()),
            new(8, 1, "Alice", "Awesome work everyone. Let's sync up at 3pm.", now.AddMinutes(-10), null, new List<Reaction>
            {
                new("👍", new List<string> { "Bob", "Carol", "Dave", "Eve", "Frank" }),
            }),
            new(9, 1, "Bob", "Sounds good! I'll prepare the demo.", now.AddMinutes(-2), null, new List<Reaction>()),

            new(10, 2, "Dave", "PR #423 is ready for review — refactored the auth module.", now.AddHours(-6), null, new List<Reaction>
            {
                new("👀", new List<string> { "Alice", "Frank" }),
            }),
            new(11, 2, "Frank", "I'll take a look after lunch.", now.AddHours(-5), null, new List<Reaction>()),
            new(12, 2, "Alice", "The CI pipeline is running slow today. Anyone else noticing?", now.AddHours(-2), null, new List<Reaction>
            {
                new("👍", new List<string> { "Dave", "Bob" }),
            }),
            new(13, 2, "Bob", "Yeah, looks like the runner pool is under-provisioned.", now.AddHours(-1.5), 12, new List<Reaction>()),
            new(14, 2, "Dave", "I'll file an infra ticket.", now.AddMinutes(-30), 12, new List<Reaction>
            {
                new("🙏", new List<string> { "Alice" }),
            }),

            new(15, 3, "Carol", "New mockups for the dashboard are in Figma. Please review!", now.AddHours(-3), null, new List<Reaction>
            {
                new("🎨", new List<string> { "Eve" }),
                new("👍", new List<string> { "Alice", "Bob" }),
            }),
            new(16, 3, "Eve", "Love the color palette. Small note: the sidebar feels a bit cramped on mobile.", now.AddHours(-2), 15, new List<Reaction>()),
            new(17, 3, "Carol", "Good catch, I'll adjust the breakpoints.", now.AddHours(-1.5), 15, new List<Reaction>
            {
                new("👍", new List<string> { "Eve" }),
            }),

            new(18, 4, "Bob", "Anyone up for lunch at noon?", now.AddHours(-4), null, new List<Reaction>
            {
                new("🍕", new List<string> { "Dave", "Eve", "Frank" }),
            }),
            new(19, 4, "Eve", "Count me in!", now.AddHours(-3.5), 18, new List<Reaction>()),
            new(20, 4, "Frank", "Just saw the funniest bug — the tooltip follows you across pages 😂", now.AddMinutes(-20), null, new List<Reaction>
            {
                new("😂", new List<string> { "Alice", "Bob", "Carol", "Dave" }),
            }),
        };

        _nextMessageId = _messages.Max(m => m.Id) + 1;
    }

    public Task<List<Channel>> GetChannelsAsync()
    {
        return Task.FromResult(_channels.ToList());
    }

    public Task<List<Message>> GetMessagesAsync(int channelId, int skip, int take)
    {
        // Return only root messages (not replies) for the main channel view
        var messages = _messages
            .Where(m => m.ChannelId == channelId && m.ReplyToId == null)
            .OrderBy(m => m.SentAt)
            .Skip(skip)
            .Take(take)
            .ToList();
        return Task.FromResult(messages);
    }

    public Task<Message> SendMessageAsync(int channelId, string content, int? replyToId)
    {
        var msg = new Message(_nextMessageId++, channelId, "You", content, DateTime.UtcNow, replyToId, new List<Reaction>());
        _messages.Add(msg);
        return Task.FromResult(msg);
    }

    public Task<List<Message>> GetThreadAsync(int rootMessageId)
    {
        var root = _messages.FirstOrDefault(m => m.Id == rootMessageId);
        if (root == null) return Task.FromResult(new List<Message>());

        var replies = _messages
            .Where(m => m.ReplyToId == rootMessageId)
            .OrderBy(m => m.SentAt)
            .ToList();

        var thread = new List<Message> { root };
        thread.AddRange(replies);
        return Task.FromResult(thread);
    }

    public Task AddReactionAsync(int messageId, string emoji)
    {
        var msg = _messages.FirstOrDefault(m => m.Id == messageId);
        if (msg != null)
        {
            var existing = msg.Reactions.FirstOrDefault(r => r.Emoji == emoji);
            if (existing != null)
            {
                if (!existing.Users.Contains("You"))
                    existing.Users.Add("You");
            }
            else
            {
                msg.Reactions.Add(new Reaction(emoji, new List<string> { "You" }));
            }
        }
        return Task.CompletedTask;
    }

    public Task MarkChannelReadAsync(int channelId)
    {
        var idx = _channels.FindIndex(c => c.Id == channelId);
        if (idx >= 0)
        {
            var ch = _channels[idx];
            _channels[idx] = ch with { UnreadCount = 0 };
        }
        return Task.CompletedTask;
    }

    /// <summary>Gets the reply count for a given root message.</summary>
    public int GetReplyCount(int rootMessageId)
    {
        return _messages.Count(m => m.ReplyToId == rootMessageId);
    }

    /// <summary>Gets thread summaries for root messages that have replies.</summary>
    public Task<List<ThreadSummary>> GetThreadSummariesAsync(int channelId)
    {
        var rootIds = _messages
            .Where(m => m.ChannelId == channelId && m.ReplyToId == null)
            .Select(m => m.Id)
            .ToHashSet();

        var summaries = _messages
            .Where(m => m.ReplyToId.HasValue && rootIds.Contains(m.ReplyToId.Value))
            .GroupBy(m => m.ReplyToId!.Value)
            .Select(g => new ThreadSummary(g.Key, g.Count(), g.Max(m => m.SentAt)))
            .ToList();

        return Task.FromResult(summaries);
    }
}

