@page "/chat"
@rendermode InteractiveServer
@using sv_4f1484f67c544667b39d1004e516a207.Services
@inject IChatService ChatService
@inject IJSRuntime JS

<PageTitle>Chat</PageTitle>

<div class="chat-layout">
    @* ── Left Sidebar: Channel List ── *@
    <aside class="chat-sidebar">
        <div class="sidebar-header">
            <h3>Channels</h3>
        </div>
        <ul class="channel-list">
            @if (_channels is not null)
            {
                @foreach (var channel in _channels)
                {
                    <li class="channel-item @(channel.Id == _activeChannelId ? "active" : "")"
                        @onclick="() => SelectChannelAsync(channel.Id)">
                        <div class="channel-info">
                            <span class="channel-name"># @channel.Name</span>
                            <span class="channel-desc">@TruncateDescription(channel.Description)</span>
                        </div>
                        @if (channel.UnreadCount > 0)
                        {
                            <span class="unread-badge">@channel.UnreadCount</span>
                        }
                    </li>
                }
            }
        </ul>
    </aside>

    @* ── Main Message Area ── *@
    <section class="chat-main @(_threadOpen ? "" : "chat-main-full")">
        @if (_activeChannel is not null)
        {
            <div class="main-header">
                <h2># @_activeChannel.Name</h2>
                <span class="main-header-desc">@_activeChannel.Description</span>
            </div>

            <div class="message-list" @ref="_messageListRef" @onscroll="HandleScrollAsync">
                @if (_loadingOlder)
                {
                    <div class="loading-indicator">Loading older messages…</div>
                }
                @if (_messages is not null)
                {
                    @foreach (var msg in _messages)
                    {
                        <div class="message-row" @onmouseenter="() => _hoveredMessageId = msg.Id"
                             @onmouseleave="() => _hoveredMessageId = null">
                            <div class="message-bubble">
                                <div class="message-header">
                                    <span class="message-author">@msg.Author</span>
                                    <span class="message-time">@FormatRelativeTime(msg.SentAt)</span>
                                </div>
                                <div class="message-content">@msg.Content</div>

                                @if (msg.Reactions.Count > 0)
                                {
                                    <div class="reaction-row">
                                        @foreach (var reaction in msg.Reactions)
                                        {
                                            <button class="reaction-badge" title="@string.Join(", ", reaction.Users)"
                                                    @onclick="() => AddReactionAsync(msg.Id, reaction.Emoji)">
                                                @reaction.Emoji @reaction.Users.Count
                                            </button>
                                        }
                                    </div>
                                }

                                @{ var summary = GetThreadSummary(msg.Id); }
                                @if (summary is not null)
                                {
                                    <button class="thread-link" @onclick="() => OpenThreadAsync(msg.Id)">
                                        💬 @summary.ReplyCount @(summary.ReplyCount == 1 ? "reply" : "replies")
                                    </button>
                                }
                            </div>

                            @if (_hoveredMessageId == msg.Id)
                            {
                                <div class="message-actions">
                                    <button class="action-btn" title="Reply in thread"
                                            @onclick="() => OpenThreadAsync(msg.Id)">💬</button>
                                    <button class="action-btn" title="Add reaction"
                                            @onclick="() => ToggleEmojiPicker(msg.Id)">😀</button>
                                </div>

                                @if (_emojiPickerMessageId == msg.Id)
                                {
                                    <div class="emoji-picker">
                                        @foreach (var emoji in _commonEmojis)
                                        {
                                            <button class="emoji-option"
                                                    @onclick="() => AddReactionAsync(msg.Id, emoji)">@emoji</button>
                                        }
                                    </div>
                                }
                            }
                        </div>
                    }
                }
            </div>

            <div class="message-input-area">
                <textarea @bind="_newMessage" @bind:event="oninput"
                          @onkeydown="HandleMessageKeyDownAsync"
                          placeholder="Message #@_activeChannel.Name" rows="1"></textarea>
                <button class="send-btn" @onclick="SendMessageAsync" disabled="@string.IsNullOrWhiteSpace(_newMessage)">
                    Send
                </button>
            </div>
        }
        else
        {
            <div class="no-channel-selected">
                <p>Select a channel to start chatting</p>
            </div>
        }
    </section>

    @* ── Right Panel: Thread View ── *@
    @if (_threadOpen && _threadMessages is not null)
    {
        <aside class="chat-thread-panel">
            <div class="thread-header">
                <h3>Thread</h3>
                <button class="close-thread-btn" @onclick="CloseThread">✕</button>
            </div>

            @if (_threadMessages.Count > 0)
            {
                <div class="thread-root-quote">
                    <span class="message-author">@_threadMessages[0].Author</span>
                    <p>@_threadMessages[0].Content</p>
                </div>
            }

            <div class="thread-message-list">
                @foreach (var reply in _threadMessages.Skip(1))
                {
                    <div class="thread-message">
                        <div class="message-header">
                            <span class="message-author">@reply.Author</span>
                            <span class="message-time">@FormatRelativeTime(reply.SentAt)</span>
                        </div>
                        <div class="message-content">@reply.Content</div>
                        @if (reply.Reactions.Count > 0)
                        {
                            <div class="reaction-row">
                                @foreach (var reaction in reply.Reactions)
                                {
                                    <button class="reaction-badge" title="@string.Join(", ", reaction.Users)"
                                            @onclick="() => AddReactionAsync(reply.Id, reaction.Emoji)">
                                        @reaction.Emoji @reaction.Users.Count
                                    </button>
                                }
                            </div>
                        }
                    </div>
                }
            </div>

            <div class="thread-input-area">
                <textarea @bind="_threadReply" @bind:event="oninput"
                          @onkeydown="HandleThreadKeyDownAsync"
                          placeholder="Reply…" rows="1"></textarea>
                <button class="send-btn" @onclick="SendThreadReplyAsync"
                        disabled="@string.IsNullOrWhiteSpace(_threadReply)">Reply</button>
            </div>
        </aside>
    }
</div>

@code {
    private List<Channel>? _channels;
    private List<Message>? _messages;
    private List<ThreadSummary>? _threadSummaries;
    private List<Message>? _threadMessages;

    private Channel? _activeChannel;
    private int _activeChannelId;
    private bool _threadOpen;
    private int? _activeThreadRootId;

    private string _newMessage = "";
    private string _threadReply = "";

    private int? _hoveredMessageId;
    private int? _emojiPickerMessageId;

    private bool _loadingOlder;
    private int _messageSkip;
    private const int PageSize = 50;

    private ElementReference _messageListRef;

    private static readonly string[] _commonEmojis = { "👍", "❤️", "😂", "🎉", "👀", "🙏" };

    protected override async Task OnInitializedAsync()
    {
        _channels = await ChatService.GetChannelsAsync();
        if (_channels.Count > 0)
        {
            await SelectChannelAsync(_channels[0].Id);
        }
    }

    private async Task SelectChannelAsync(int channelId)
    {
        _activeChannelId = channelId;
        _activeChannel = _channels?.FirstOrDefault(c => c.Id == channelId);
        _messageSkip = 0;
        _messages = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
        _threadSummaries = await GetThreadSummariesForChannelAsync(channelId);
        await ChatService.MarkChannelReadAsync(channelId);

        // Refresh the channel list to show updated unread counts
        _channels = await ChatService.GetChannelsAsync();

        _emojiPickerMessageId = null;
        _hoveredMessageId = null;

        await ScrollToBottomAsync();
    }

    private async Task HandleScrollAsync()
    {
        // JS interop to detect scroll-to-top for pagination
        var scrollTop = await JS.InvokeAsync<double>("eval", "document.querySelector('.message-list')?.scrollTop ?? 1");
        if (scrollTop < 1 && !_loadingOlder && _messages is not null && _messages.Count >= PageSize)
        {
            await LoadOlderMessagesAsync();
        }
    }

    private async Task LoadOlderMessagesAsync()
    {
        if (_loadingOlder) return;
        _loadingOlder = true;
        StateHasChanged();

        _messageSkip += PageSize;
        var older = await ChatService.GetMessagesAsync(_activeChannelId, _messageSkip, PageSize);
        if (older.Count > 0)
        {
            _messages = older.Concat(_messages!).ToList();
        }

        _loadingOlder = false;
    }

    private async Task SendMessageAsync()
    {
        if (string.IsNullOrWhiteSpace(_newMessage)) return;
        var msg = await ChatService.SendMessageAsync(_activeChannelId, _newMessage.Trim(), null);
        _messages?.Add(msg);
        _newMessage = "";
        await ScrollToBottomAsync();
    }

    private async Task HandleMessageKeyDownAsync(KeyboardEventArgs e)
    {
        if (e.Key == "Enter" && !e.ShiftKey)
        {
            await SendMessageAsync();
        }
    }

    private async Task OpenThreadAsync(int rootMessageId)
    {
        _activeThreadRootId = rootMessageId;
        _threadMessages = await ChatService.GetThreadAsync(rootMessageId);
        _threadOpen = true;
        _threadReply = "";
    }

    private void CloseThread()
    {
        _threadOpen = false;
        _threadMessages = null;
        _activeThreadRootId = null;
        _threadReply = "";
    }

    private async Task SendThreadReplyAsync()
    {
        if (string.IsNullOrWhiteSpace(_threadReply) || _activeThreadRootId is null) return;
        var msg = await ChatService.SendMessageAsync(_activeChannelId, _threadReply.Trim(), _activeThreadRootId);
        _threadMessages?.Add(msg);
        _threadReply = "";

        // Refresh thread summaries so the main view shows updated reply counts
        _threadSummaries = await GetThreadSummariesForChannelAsync(_activeChannelId);
    }

    private async Task HandleThreadKeyDownAsync(KeyboardEventArgs e)
    {
        if (e.Key == "Enter" && !e.ShiftKey)
        {
            await SendThreadReplyAsync();
        }
    }

    private async Task AddReactionAsync(int messageId, string emoji)
    {
        await ChatService.AddReactionAsync(messageId, emoji);
        _emojiPickerMessageId = null;

        // Refresh messages to reflect the new reaction
        _messages = await ChatService.GetMessagesAsync(_activeChannelId, 0, Math.Max(_messages?.Count ?? PageSize, PageSize));
        if (_threadOpen && _activeThreadRootId is not null)
        {
            _threadMessages = await ChatService.GetThreadAsync(_activeThreadRootId.Value);
        }
    }

    private void ToggleEmojiPicker(int messageId)
    {
        _emojiPickerMessageId = _emojiPickerMessageId == messageId ? null : messageId;
    }

    private ThreadSummary? GetThreadSummary(int rootMessageId)
    {
        return _threadSummaries?.FirstOrDefault(t => t.RootMessageId == rootMessageId);
    }

    private async Task<List<ThreadSummary>> GetThreadSummariesForChannelAsync(int channelId)
    {
        if (ChatService is MockChatService mock)
        {
            return await mock.GetThreadSummariesAsync(channelId);
        }
        return new List<ThreadSummary>();
    }

    private async Task ScrollToBottomAsync()
    {
        try
        {
            await Task.Yield(); // let the DOM update
            await JS.InvokeVoidAsync("eval",
                "setTimeout(() => { const el = document.querySelector('.message-list'); if (el) el.scrollTop = el.scrollHeight; }, 50)");
        }
        catch { /* ignore during prerender */ }
    }

    private static string FormatRelativeTime(DateTime utcTime)
    {
        var diff = DateTime.UtcNow - utcTime;
        if (diff.TotalSeconds < 60) return "just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        if (diff.TotalDays < 7) return $"{(int)diff.TotalDays}d ago";
        return utcTime.ToString("MMM d, yyyy");
    }

    private static string TruncateDescription(string desc)
    {
        return desc.Length > 30 ? desc[..30] + "…" : desc;
    }
}

